        placeholder: "./\uD83E\uDDF0\uFE0Fframework/\uD83D\uDD28\uFE0Fmodules/\uD83D\uDDBC\uFE0Fassets/\uD83E\uDD7D\uFE0Fmesh/\uD83E\uDDCA\uFE0Fplaceholder.glb",
