  if (configurations.length > INTERACTIVITY_ALL_APP_LAUNCH_CAPACITY)
    failures.push(`${INTERACTIVITY_ALL_APP_LAUNCH_FILE}: ${configurations.length} configurations exceed fixed capacity ${INTERACTIVITY_ALL_APP_LAUNCH_CAPACITY}`);
